  `id` int NOT NULL AUTO_INCREMENT,
  `custom_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `lead` text COLLATE utf8mb4_unicode_ci,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '#006b9a',
  `image_url` text COLLATE utf8mb4_unicode_ci,
  `image_caption` text COLLATE utf8mb4_unicode_ci,
  `read_time` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '3 മിനിറ്റ് വായന',
  `audio_duration` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '03:00',
  `paragraphs` json DEFAULT NULL,
  `highlights` json DEFAULT NULL,
  `author_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'കേരളദേശം ന്യൂസ് ഡെസ്ക്',
  `author_designation` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'ഡെസ്ക് റിപ്പോർട്ടർ',
  `author_location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'കേരളം',
  `author_avatar` text COLLATE utf8mb4_unicode_ci,
  `author_verified` tinyint(1) DEFAULT '1',
  `district` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `views` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '1',
  `views_count` int DEFAULT '1',
  `likes_count` int DEFAULT '0',
  `tags` json DEFAULT NULL,
  `is_breaking` tinyint(1) DEFAULT '0',
  `is_trending` tinyint(1) DEFAULT '0',
  `is_headline` tinyint(1) DEFAULT '0',
  `published_at` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `custom_id` (`custom_id`),
  KEY `idx_category` (`category`),
  KEY `idx_district` (`district`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

