INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (1, 'wayanad-tunnel', 'വയനാട് ഇരട്ട തുരങ്കപാത നിർമാണത്തിന് കേന്ദ്ര പരിസ്ഥിതി അനുമതി; മലയോര ഹൈവേ വികസനത്തിൽ നിർണായക വഴിത്തിരിവ്', 'കോഴിക്കോട് ആനക്കാംപൊയിൽ-കള്ളാടി-മേപ്പാടി തുരങ്കപാത യാഥാർഥ്യമാകുമ്പോൾ താമരശ്ശേരി ചുരത്തിലെ ഗതാഗതക്കുരുക്കിന് ശാശ്വത പരിഹാരം; 2,134 കോടി രൂപയുടെ നിർമാണ പദ്ധതിക്ക് സംസ്ഥാന മന്ത്രിസഭയുടെ പ്രത്യേക അനുമതി.', 'വികസനം & അടിസ്ഥാനസൗകര്യം', '#006b9a', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=80', 'നിർദ്ദിഷ്ട വയനാട് തുരങ്കപാതയുടെ ആനക്കാംപൊയിൽ പ്രവേശന കവാടം സ്ഥിതി ചെയ്യുന്ന മലനിരകളുടെ ആകാശദൃശ്യം.', '4 മിനിറ്റ് വായന', '03:45', '["കോഴിക്കോട് ജില്ലയിലെ ആനക്കാംപൊയിലിനെയും വയനാട് ജില്ലയിലെ മേപ്പാടിയെയും ബന്ധിപ്പിച്ച് നിർമിക്കുന്ന ചരിത്രപ്രസിദ്ധമായ ഇരട്ട തുരങ്കപാത നിർമാണത്തിന് കേന്ദ്ര വനം പരിസ്ഥിതി മന്ത്രാലയത്തിന്റെ അന്തിമ അനുമതി ലഭിച്ചു. വയനാട് ചുരത്തിലെ നിത്യേനയുള്ള ഗതാഗതക്കുരുക്കുകൾക്കും പ്രകൃതിക്ഷോഭങ്ങൾ മൂലമുണ്ടാകുന്ന യാത്രാതടസ്സങ്ങൾക്കും ഇതോടെ ശാശ്വത പരിഹാരമാകുമെന്ന് മുഖ്യമന്ത്രിയുടെ ഓഫീസ് അറിയിച്ചു.","2,134 കോടി രൂപ കിഫ്ബി വഴി വകയിരുത്തിയിട്ടുള്ള ഈ മെഗാ പ്രൊജക്റ്റിൽ രണ്ട് തുരങ്കങ്ങളിലായി ആകെ നാല് വരി പാതയാണ് വിഭാവനം ചെയ്തിരിക്കുന്നത്. നിർമാണ കരാർ ഉടൻ തന്നെ ഗ്ലോബൽ ടെൻഡറിലൂടെ അന്തിമമാക്കുമെന്നും ഈ വർഷം അവസാനത്തോടെ തുരങ്കം തുരക്കുന്ന പ്രവർത്തനങ്ങൾക്ക് തുടക്കമാകുമെന്നും പൊതുമരാമത്ത് വകുപ്പ് അറിയിച്ചു.","പദ്ധതിക്കായി 12.5 ഹെക്ടർ വനഭൂമിയാണ് വിട്ടുകിട്ടേണ്ടിയിരുന്നത്. ഇതിന് പകരമായി കാസർഗോഡ്, കണ്ണൂർ ജില്ലകളിലായി തത്തുല്യമായ റവന്യൂ ഭൂമി വനവൽക്കരണത്തിനായി വനംവകുപ്പിന് കൈമാറിയിട്ടുണ്ട്. തുരങ്കപാത യാഥാർത്ഥ്യമാകുന്നതോടെ കൊച്ചി, കോഴിക്കോട് വിമാനത്താവളങ്ങളിൽ നിന്ന് വയനാട്ടിലേക്കും മൈസൂരു, ബെംഗളൂരു നഗരങ്ങളിലേക്കുമുള്ള ചരക്കുഗതാഗത ദൂരം ഗണ്യമായി കുറയും."]', '["8.11 കിലോമീറ്റർ നീളമുള്ള ഇരട്ട തുരങ്കം രാജ്യത്തെ മൂന്നാമത്തെ വലിയ തുരങ്കപാതയാകും.","കൊങ്കൺ റെയിൽവേ കോർപ്പറേഷനാണ് പദ്ധതിയുടെ നിർമാണ നിർവഹണ ഏജൻസി.","താമരശ്ശേരി ചുരത്തിലെ യാത്രാസമയം ഒന്നര മണിക്കൂറോളം ലാഭിക്കാൻ സാധിക്കും.","പരിസ്ഥിതി സൗഹൃദ ഡ്രിൽ & ബ്ലാസ്റ്റ് സാങ്കേതികവിദ്യ ഉപയോഗിച്ചാകും തുരങ്കം പണിയുക."]', 'കെ. ആർ. നാരായണൻ', 'സീനിയർ ചീഫ് റിപ്പോർട്ടർ', 'തിരുവനന്തപുരം', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'വയനാട്', '', '18.4k', 2, 0, '["WayanadTunnel","KeralaInfrastructure","HighrangeNews","Kozhikode"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (2, 'kerala-budget-infra', 'സംസ്ഥാന ബജറ്റിൽ അടിസ്ഥാന സൗകര്യ വികസനത്തിന് മുൻഗണന; തീരദേശ-മലയോര ഹൈവേകൾക്ക് അധിക വിഹിതം', 'സംസ്ഥാനത്തിന്റെ മൊത്തം ആഭ്യന്തര ഉൽപ്പാദനത്തിൽ 6.8% വളർച്ച ലക്ഷ്യമിട്ട് ധനമന്ത്രി പുതിയ വികസന പാക്കേജ് പ്രഖ്യാപിച്ചു.', 'ഭരണം & നിയമസഭ', '#C8102E', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80', '', '3 മിനിറ്റ് വായന', '03:00', '["നിയമസഭയിൽ അവതരിപ്പിച്ച പുതുക്കിയ ധനബജറ്റിൽ അടിസ്ഥാന സൗകര്യങ്ങൾക്കും വിവരസാങ്കേതിക രംഗത്തിനും റെക്കോർഡ് തുക അനുവദിച്ചു.","തീരദേശ ഹൈവേയുടെയും മലയോര ഹൈവേയുടെയും നിർമാണ വേഗത വർധിപ്പിക്കാൻ 1,500 കോടി രൂപ നീക്കിവെച്ചതായി ധനമന്ത്രി അറിയിച്ചു."]', '[]', 'എസ്. സുരേഷ് കുമാർ', 'സ്പെഷ്യൽ കറസ്പോണ്ടന്റ്', 'തിരുവനന്തപുരം', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'തിരുവനന്തപുരം', '', '12.8k', 1, 0, '["KeralaBudget","Economy","StateAssembly"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (3, 'thiruvananthapuram-metro', 'തിരുവനന്തപുരം ലൈറ്റ് മെട്രോ: പുതിയ ഡിപിആർ കേന്ദ്രാനുമതിക്കായി സമർപ്പിച്ചു', 'പള്ളിപ്പുറം ടെക്‌നോസിറ്റി മുതൽ കരമന വരെയും രണ്ടാം ഘട്ടത്തിൽ നെയ്യാറ്റിൻകരയിലേക്കും നീളുന്ന പദ്ധതിക്ക് ഭരണാനുമതി.', 'നഗരവികസനം', '#006b9a', 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=800&q=80', '', '3 മിനിറ്റ് വായന', '03:00', '["തലസ്ഥാന നഗരിയിലെ യാത്രാക്ലേശത്തിന് പരിഹാരം കാണുന്ന തിരുവനന്തപുരം മെട്രോ പദ്ധതിയുടെ സമഗ്ര ഡിപിആർ കൊച്ചി മെട്രോ റെയിൽ ലിമിറ്റഡ് (കെഎംആർഎൽ) സമർപ്പിച്ചു."]', '[]', 'അനുപമ മേനോൻ', 'സിറ്റി ബ്യൂറോ ചീഫ്', 'തിരുവനന്തപുരം', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'തിരുവനന്തപുരം', '', '9.5k', 1, 0, '["Metro","UrbanTransit","Trivandrum"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (4, 'vizhinjam-commercial-shipping', 'വിഴിഞ്ഞം അന്താരാഷ്ട്ര തുറമുഖത്ത് വാണിജ്യ കപ്പലുകളുടെ തിരക്ക്; ദക്ഷിണേഷ്യൻ ട്രാൻസ്ഷിപ്പ്മെന്റ് ഹബ്ബായി വളരുന്നു', 'പ്രതിമാസം കൈകാര്യം ചെയ്യുന്ന കണ്ടെയ്നറുകളുടെ എണ്ണത്തിൽ 45% വളർച്ച; അന്താരാഷ്ട്ര ഷിപ്പിംഗ് കമ്പനികൾ വിഴിഞ്ഞത്തെ പ്രധാന തുറമുഖമാക്കി മാറ്റി.', 'ബിസിനസ്', '#005277', 'https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=800&q=80', '', '4 മിനിറ്റ് വായന', '03:00', '["വിഴിഞ്ഞം അന്താരാഷ്ട്ര തുറമുഖത്ത് ലോകത്തെ ഏറ്റവും വലിയ മദർഷിപ്പുകൾ ഉൾപ്പെടെ തുടർച്ചയായി ബെർത്ത് ചെയ്യുന്നതോടെ കേരളത്തിന്റെ സാമ്പത്തിക രംഗത്ത് വൻ കുതിച്ചുചാട്ടം.","തുറമുഖവുമായി ബന്ധപ്പെട്ട് ലോജിസ്റ്റിക്സ് പാർക്കുകൾ, റോഡ്-റെയിൽ കണക്റ്റിവിറ്റി വികസനം എന്നിവ അതിവേഗം പുരോഗമിക്കുകയാണ്."]', '[]', 'അനുപമ മേനോൻ', 'ബിസിനസ് എഡിറ്റർ', 'തിരുവനന്തപുരം', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'തിരുവനന്തപുരം', '', '28.4k', 1, 0, '["VizhinjamPort","Shipping","MaritimeTrade","Economy"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (5, 'ipl-sanju-samson-century', 'ഐപിഎല്ലിൽ സഞ്ജു സാംസണിന്റെ ക്യാപ്റ്റൻ ഇന്നിംഗ്സ്: രാജസ്ഥാന് ത്രില്ലർ വിജയം', 'അവസാന ഓവറിൽ സിക്സറുകളുടെ പെരുമഴ തീർത്ത് സഞ്ജുവിന്റെ വെടിക്കെട്ട് പ്രകടനം; മലയാളി ക്രിക്കറ്റ് പ്രേമികൾക്ക് ആവേശപ്പൂരം.', 'സ്പോർട്സ്', '#15803d', 'https://images.unsplash.com/photo-1531415074868-036b1c57e329?auto=format&fit=crop&w=800&q=80', '', '3 മിനിറ്റ് വായന', '03:00', '["ഐപിഎല്ലിലെ ആവേശകരമായ മത്സരത്തിൽ രാജസ്ഥാൻ റോയൽസ് ക്യാപ്റ്റൻ സഞ്ജു സാംസൺ പുറത്തെടുത്ത മാസ്മരിക ഇന്നിംഗ്സ് ടീമിന് അവിസ്മരണീയ വിജയം സമ്മാനിച്ചു.","48 പന്തിൽ നിന്ന് 92 റൺസ് അടിച്ചുകൂട്ടിയ സഞ്ജു മത്സരത്തിലെ താരമായി തെരഞ്ഞെടുക്കപ്പെട്ടു."]', '[]', 'അഭിലാഷ് നായർ', 'സ്പോർട്സ് എഡിറ്റർ', 'തൃശ്ശൂർ', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'തൃശ്ശൂർ', '', '36.8k', 1, 0, '["SanjuSamson","IPL2025","Cricket","Sports"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (6, 'un-climate-summit-declaration', 'ആഗോള കാലാവസ്ഥാ ഉച്ചകോടിയിൽ ചരിത്രപരമായ ധാരണാപത്രം: പുനരുപയോഗ ഊർജത്തിന് 100 ബില്യൺ ഡോളർ പാക്കേജ്', 'ആഗോളതാപനം 1.5 ഡിഗ്രിയിൽ താഴെ നിർത്താൻ വികസിത-വികസ്വര രാജ്യങ്ങൾ സംയുക്ത കർമപദ്ധതിക്ക് അംഗീകാരം നൽകി.', 'ലോകം', '#006b9a', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=800&q=80', '', '4 മിനിറ്റ് വായന', '03:00', '["ഐക്യരാഷ്ട്രസഭയുടെ ആഭിമുഖ്യത്തിൽ ജനീവയിൽ സമാപിച്ച അന്താരാഷ്ട്ര കാലാവസ്ഥാ ഉച്ചകോടിയിൽ കാർബൺ പുറന്തള്ളൽ ഗണ്യമായി കുറയ്ക്കാൻ ലക്ഷ്യമിട്ട് നിർണായക പ്രഖ്യാപനം.","വികസ്വര രാജ്യങ്ങളിലെ ഹരിത ഊർജ പശ്ചാത്തല സൗകര്യങ്ങൾ വികസിപ്പിക്കുന്നതിനായി 100 ബില്യൺ ഡോളറിന്റെ പ്രത്യേക കാലാവസ്ഥാ ഫണ്ട് ഏർപ്പെടുത്താൻ വികസിത രാജ്യങ്ങൾ സമ്മതിച്ചു."]', '[]', 'ഡോ. ഗീത മേനോൻ', 'വിദേശകാര്യ പ്രതിനിധി', 'ജനീവ', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, '', '', '15.3k', 1, 0, '["UNClimate","GlobalAffairs","GreenEnergy","WorldNews"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (7, 'kerala-assembly-land-tribunal', 'നിയമസഭയിൽ നിർണായക ഭൂനിയമ ഭേദഗതി ബിൽ പാസാക്കി; കർഷകർക്ക് പട്ടയം വേഗത്തിലാക്കാൻ പ്രത്യേക ട്രൈബ്യൂണൽ', 'മലയോര മേഖലകളിലെ കർഷകരുടെ പതിറ്റാണ്ടുകളായുള്ള ഭൂപ്രശ്നങ്ങൾ പരിഹരിക്കാൻ ലക്ഷ്യമിട്ട് പ്രതിപക്ഷ സഹകരണത്തോടെ ബിൽ പാസാക്കി.', 'രാഷ്ട്രീയം', '#C8102E', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?auto=format&fit=crop&w=800&q=80', '', '4 മിനിറ്റ് വായന', '03:00', '["കേരള നിയമസഭയിൽ ദീർഘനേരം നീണ്ടുനിന്ന ചർച്ചകൾക്കൊടുവിൽ ചരിത്രപ്രസിദ്ധമായ ഭൂനിയമ ഭേദഗതി ബിൽ സഭ ഏകകണ്ഠമായി പാസാക്കി.","ഇടുക്കി, വയനാട്, പത്തനംതിട്ട അടക്കമുള്ള മലയോര ജില്ലകളിലെ ആയിരക്കണക്കിന് ചെറുകിട കർഷകർക്ക് ഈ തീരുമാനം വലിയ ആശ്വാസമാകും."]', '[]', 'എസ്. സുരേഷ് കുമാർ', 'സീനിയർ അസംബ്ലി കറസ്പോണ്ടന്റ്', 'തിരുവനന്തപുരം', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'തിരുവനന്തപുരം', '', '17.8k', 1, 0, '["KeralaAssembly","LandReforms","FarmersRights","Politics"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (8, 'malayalam-cinema-global-box-office', 'മലയാള സിനിമയുടെ സുവർണകാലം: ആഗോള ബോക്സ് ഓഫീസിൽ 1,000 കോടി ക്ലബ്ബിലേക്ക് കുതിപ്പ്', 'തമിഴ്‌നാട്, കർണാടക, ഗൾഫ് മേഖലകളിൽ മലയാള സിനിമകളുടെ അഭൂതപൂർവമായ മുന്നേറ്റം; ആഗോള പ്രേക്ഷകരുടെ പ്രിയപ്പെട്ട ഇൻഡസ്ട്രിയായി മോളിവുഡ്.', 'സിനിമ', '#B45309', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=800&q=80', '', '4 മിനിറ്റ് വായന', '03:00', '["കഥാകഥനത്തിലെ പുതുമയും യഥാർത്ഥ ജീവിതത്തോട് ചേർന്നുനിൽക്കുന്ന മേക്കിംഗും കൊണ്ട് ഇന്ത്യൻ സിനിമാ ലോകത്തെ അമ്പരപ്പിച്ചിരിക്കുകയാണ് മലയാള ചലച്ചിത്രങ്ങൾ.","ഒടിടി പ്ലാറ്റ്‌ഫോമുകളിലും അന്താരാഷ്ട്ര തിയേറ്ററുകളിലും ഒരേപോലെ തരംഗം സൃഷ്ടിച്ചുകൊണ്ട് ഈ വർഷത്തെ കളക്ഷൻ റെക്കോർഡുകൾ ഭേദിക്കപ്പെട്ടു."]', '[]', 'ദിലീപ് കുമാർ', 'സിനിമാ നിരൂപകൻ', 'കൊച്ചി', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'എറണാകുളം', '', '42.5k', 1, 0, '["Mollywood","BoxOffice","MalayalamCinema","Entertainment"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (9, 'pravasi-eid-holidays', 'ഗൾഫിൽ ഈദ് അൽ ഫിത്തർ അവധികൾ പ്രഖ്യാപിച്ചു; യുഎഇയിൽ സർക്കാർ ജീവനക്കാർക്ക് 9 ദിവസത്തെ ദീർഘാവധി', 'ചന്ദ്രപ്പിറവി നിരീക്ഷണ സമിതികൾ യോഗം ചേരുന്നതോടെ പെരുന്നാൾ തീയതി അന്തിമമാക്കും; നാട്ടിലേക്കുള്ള വിമാന ടിക്കറ്റ് നിരക്കുകളിൽ വൻ വർധനവ്.', 'പ്രവാസം', '#9e001f', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=800&q=80', '', '3 മിനിറ്റ് വായന', '03:00', '["യുണൈറ്റഡ് അറബ് എമിറേറ്റ്സ് ഫെഡറൽ അതോറിറ്റി സർക്കാർ, അർദ്ധസർക്കാർ മേഖലകൾക്കുള്ള ഈദ് അൽ ഫിത്തർ അവധികൾ പ്രഖ്യാപിച്ചു.","പ്രവാസികൾ കുടുംബസമേതം ആഘോഷങ്ങളിലേക്ക് കടക്കുമ്പോൾ കേരളത്തിലേക്കുള്ള വിമാന സർവീസുകളിൽ സീറ്റുകൾ മുൻകൂട്ടി റിസർവ് ചെയ്യപ്പെട്ടു കഴിഞ്ഞു."]', '[]', 'ഫൈസൽ ബാബു', 'ഗൾഫ് ബ്യൂറോ ചീഫ്', 'ദുബായ്', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, '', 'uae', '24.6k', 1, 0, '["EidMubarak","GulfNews","UAEHolidays","Pravasi"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (10, 'opinion-kerala-higher-education', 'ഉന്നതവിദ്യാഭ്യാസ രംഗത്ത് കേരളം സ്വീകരിക്കേണ്ട പുതിയ വഴികൾ: സമഗ്ര വിലയിരുത്തൽ', 'യുവജനങ്ങളുടെ വിദേശപഠന കുടിയേറ്റം തടയാൻ ഗവേഷണ സൗകര്യങ്ങളും വ്യവസായ-അക്കാദമിക് സംയോജനവും കൂടുതൽ ശക്തമാക്കണം.', 'അഭിപ്രായം', '#854d0e', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=800&q=80', '', '5 മിനിറ്റ് വായന', '03:00', '["കേരളത്തിന്റെ ഉന്നത വിദ്യാഭ്യാസ രംഗം നേരിടുന്ന ഏറ്റവും വലിയ വെല്ലുവിളി പ്രതിഭാശാലികളായ വിദ്യാർത്ഥികളുടെ വൻതോതിലുള്ള വിദേശ കുടിയേറ്റമാണ്.","അന്താരാഷ്ട്ര നിലവാരത്തിലുള്ള റിസർച്ച് ലാബുകളും സ്റ്റാർട്ടപ്പ് ഇൻകുബേറ്ററുകളും കാമ്പസുകളിൽ ഒരുക്കുക വഴി ഈ പ്രവണതയ്ക്ക് ഗുണപരമായ മാറ്റം കൊണ്ടുവരാൻ സാധിക്കും."]', '[]', 'പ്രൊഫ. എം. കെ. സാനു', 'വിദ്യാഭ്യാസ ചിന്തകൻ', 'കൊച്ചി', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAxYYHCHhgyTEaleB6KsujrLK-JvitACp_ZFM9MzEdJHRi_d0C8VmnMzOMMK-u17yasy2NbId1bupaXx_4iKs7XB4NIsCyIMXn7JOo-i4lhEaGeuiJqzKaFNUK_uCGRG1iVGWYcRUi-lMTeHPm6pPJC6HutiF0Xl7HEQ7HuFeWxUUfN_nsHYk1DHLIWHirfqJMPcqiJ40oqxD3WwteEtcQZ7l_jZeoa1V71xJOQcf9qH8cfFOMF27T8', 1, 'എറണാകുളം', '', '9.2k', 1, 0, '["Education","Opinion","YouthMigration","KeralaFuture"]', 0, 0, 0, '2026, ഒക്ടോ 23 5:53 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (11, 'ai-research-park-in-kerala-launched-with-10000-jobs-4380', 'AI Research Park in Kerala launched with 10000 jobs', 'Kochi Infopark will house the new AI Research Park with 10000 jobs approved by cabinet.', 'ബിസിനസ് & സമ്പദ്‌വ്യവസ്ഥ', '#006b9a', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80', 'കേരളത്തിലെ സ്റ്റാർട്ടപ്പ് മിഷൻ സംരംഭകർ', '3 മിനിറ്റ് വായന', '03:00', '["സംസ്ഥാനത്ത് സുപ്രധാന വികസന പദ്ധതികൾക്ക് വേഗമേറ്റാൻ മന്ത്രിസഭാ യോഗം തീരുമാനിച്ചു.","വിവിധ മേഖലകളിലെ വിദഗ്ധരുടെ നിർദേശങ്ങൾ പരിഗണിച്ചാണ് പദ്ധതി രൂപരേഖ തയ്യാറാക്കിയിട്ടുള്ളത്."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'എറണാകുളം', '', '1', 1, 0, '["Kerala","News","Latest"]', 0, 0, 0, '2026, ഒക്ടോ 24 9:45 AM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (12, 'kmcc-6400', 'ഖത്തര്‍ KMCC കവര്‍ച്ചയില്‍ ആദ്യ നടപടി; വ്യവസായി റസാഖ് റൊട്ടാനയെ പുറത്താക്കി മുസ്‌ലിം ലീഗ്', 'കെഎംസിസി അടക്കമുള്ള എല്ലാ ലീഗ് പോഷക സംഘടനകളില്‍ നിന്നും പുറത്താക്കി', 'രാഷ്ട്രീയം', '#C8102E', 'https://www.reporterlive.com/storage/gallery/2026/10/24/kmcc.jpg', 'തിരുവനന്തപുരം ഗവൺമെന്റ് സെക്രട്ടേറിയറ്റ് മന്ദിരം', '3 മിനിറ്റ് വായന', '03:00', '["കോഴിക്കോട്: ഖത്തറിലെ കെഎംസിസി ഓഫീസില്‍ നടന്ന കോടികളുടെ കവര്‍ച്ചാ കേസില്‍ ആരോപണം നേരിട്ട വ്യവസായി റസാഖ് റൊട്ടാനയെ പുറത്താക്കി മുസ്‌ലിം ലീഗ്. കെഎംസിസി അടക്കമുള്ള എല്ലാ ലീഗ് പോഷക സംഘടനകളില്‍ നിന്നും പുറത്താക്കിയതായാണ് അറിയിപ്പ്. സംസ്ഥാന ലീഗ് കമ്മിറ്റിയാണ് റസാഖിനെ പുറത്താക്കിയത്.","നേരത്തെ കീഴടങ്ങിയ നാലാം പ്രതി ബാലകൃഷ്ണന്റെ മൊഴിയിലും ഇയാള്‍ പുറത്തുവിട്ട വീഡിയോയിലും റസാഖ് റൊട്ടാനയുടെ പേരുണ്ട്. അതൊടൊപ്പം മുഖ്യപ്രതിയായ ബോംബെ ഷാജിയുടെ ശബ്ദ സന്ദേശം പുറത്തുവന്നിരുന്നു. അതിലും റസാഖിന്റെ പേര് പരാമര്‍ശിക്കുന്നുണ്ട്. ഈ ആരോപണങ്ങളെല്ലാം റസാഖ് റൊട്ടാന നിഷേധിച്ചു. തനിക്കെതിരെ ഒരു വിഭാഗം നീക്കം നടത്തുന്നതായാണ് ഇയാള്‍ നല്‍കിയ വിശദീകരണം. ആരെയും സംരക്ഷിക്കുന്ന നിലപാട് ലീഗില്‍ നിന്ന് ഉണ്ടാകില്ലെന്ന് പിഎംഎ സലാം കഴിഞ്ഞ ദിവസം പറഞ്ഞിരുന്നു. ലീഗുമായി ബന്ധപ്പെട്ട ആരെങ്കിലും കവര്‍ച്ചയ്ക്ക് പിന്നിലുണ്ടെങ്കില്‍ കൃത്യമായ നടപടിയെടുക്കുമെന്നാണ് സലാം പറഞ്ഞത്.","2025 സെപ്റ്റംബര്‍ 18നാണ് കേസിനാസ്പദമായ സംഭവം നടക്കുന്നത്. കെഎംസിസിയുടെ അല്‍ തുമാമയിലെ ഓഫീസിലെ ലോക്കര്‍ തകര്‍ത്ത് എട്ട് കോടിയോളം ഇന്ത്യന്‍ രൂപയാണ് കവര്‍ന്നത്. കെഎംസിസിയുടെ സ്നേഹ സുരക്ഷാ പദ്ധതിക്കായി സമാഹരിച്ച തുകയായിരുന്നു മോഷ്ടിക്കപ്പെട്ടത്. അംഗങ്ങള്‍ക്ക് അസുഖമോ മരണമോ സംഭവിച്ചാല്‍ 50,000 രൂപ മുതല്‍ 10 ലക്ഷം രൂപ വരെ നല്‍കാനായി അംഗങ്ങളില്‍ നിന്ന് പ്രതിമാസം 20 റിയാല്‍ വീതം പിരിവെടുത്തായിരുന്നു ഈ തുക സമാഹരിച്ചിരുന്നത്.","പണം നഷ്ടമായതിന് പിന്നാലെ കെഎംസിസി നല്‍കിയ പരാതിയുടെ അടിസ്ഥാനത്തില്‍ ഖത്തര്‍ പൊലീസും കേരളത്തിലെ ഗൂഢാലോചനയെ മുന്‍നിര്‍ത്തി കൊയിലാണ്ടി പൊലീസും അന്വേഷണം നടത്തുന്നതിനിടെയാണ് നാലാം പ്രതി ബാലകൃഷ്ണന്‍ കീഴടങ്ങുന്നത്. വെല്‍ഡിങ് ജോലിക്കാരനായ തന്നെ അറബിയുടെ വീട്ടില്‍ ഒരു ജോലിയുണ്ടെന്ന് പറഞ്ഞ് കേസിലെ ഒന്നാം പ്രതി ബോംബെ ഷാജിയാണ് ഖത്തറിലെത്തിച്ചതെന്നാണ് ബാലകൃഷ്ണന്‍ അവകാശപ്പെടുന്നത്. കെഎംസിസി ഓഫീസിലെ സ്ട്രോങ് റൂം ഗ്യാസ് കട്ടര്‍ ഉപയോഗിച്ച് തുറക്കാന്‍ സംഘം ആവശ്യപ്പെട്ടുവെന്നും ഇവിടെയെത്തിയപ്പോഴാണ് കെഎംസിസിയുടെ ഓഫീസാണെന്ന് മനസിലായതെന്നും ഭീഷണിപ്പെടുത്തിയത് കൊണ്ടാണ് കവര്‍ച്ചയില്‍ സഹായിച്ചതെന്നും ബാലകൃഷ്ണന്‍ മൊഴി നല്‍കിയിട്ടുണ്ട്."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'പ്രവാസം / ഗൾഫ്', '', '1', 6, 0, '["Kerala","News","Latest"]', 0, 0, 0, '2026, ഒക്ടോ 24 5:42 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (13, '-8122', '''രക്ഷാപ്രവർത്തന'' കേസ് അട്ടിമറി; എം ആർ അജിത് കുമാറിൻ്റെ സസ്പെൻഷൻ നീട്ടി', 'നാല് മാസത്തേക്കാണ് സസ്‌പെൻഷൻ നീട്ടിയത്', 'ഭരണം & നിയമസഭ', '#C8102E', 'https://www.reporterlive.com/storage/gallery/7nT6TPyKLMD59sTgSE4c5fXTAfKkpzEKyW3vbADi.jpg', 'തിരുവനന്തപുരം ഗവൺമെന്റ് സെക്രട്ടേറിയറ്റ് മന്ദിരം', '3 മിനിറ്റ് വായന', '03:00', '["തിരുവനന്തപുരം: ആലപ്പുഴയിലെ വിവാദ രക്ഷാപ്രവർത്തന കേസ് അട്ടിമറിക്കാൻ ശ്രമിച്ചതിൽ എം ആർ അജിത്കുമാറിന്റെ സസ്‌പെൻഷൻ നീട്ടി. നാല് മാസത്തേക്കാണ് സസ്‌പെൻഷൻ നീട്ടിയത്. മൂന്ന് മാസം കൂടുമ്പോഴുള്ള പരിശോധനയിലാണ് സസ്‌പെൻഷൻ നീട്ടാൻ തീരുമാനിച്ചത്.\\n\\nനവകേരള യാത്രയ്ക്കിടെ മുൻ മുഖ്യമന്ത്രി പിണറായി വിജയൻറെ ഗൺമാൻമാർ കെഎസ്‌യു പ്രവർത്തകരെ ക്രൂരമായി മർദിച്ചതാണ് രക്ഷാപ്രവർത്തന കേസ്. ഈ കേസ് എഡിജിപി ആയിരുന്ന എം ആര്‍ അജിത് കുമാര്‍ അട്ടിമറിച്ചു എന്നാണ് എസ്‌ഐടി കണ്ടെത്തല്‍. മര്‍ദ്ദന കേസിലെ അന്വേഷണ റിപ്പോര്‍ട്ട് തിരുത്തിയെന്നും തെളിവില്ലെന്ന് വരുത്തി പ്രതികളെ രക്ഷിക്കാന്‍ ശ്രമം നടത്തിയെന്നുമായിരുന്നു അജിത് കുമാറിനെതിരെ എസ്ഐടിയുടെ കണ്ടെത്തലുണ്ട്.","എഡിജിപി അജിത് കുമാര്‍ പറഞ്ഞിട്ടാണ് തിരുത്തല്‍ നടത്തിയതെന്നാണ് എസ്ഐടി റിപ്പോര്‍ട്ടില്‍ പറയുന്നത്. അജിത് കുമാറിനെതിരെ മുന്‍ അന്വേഷണ സംഘത്തിന്റെ മൊഴി ഉള്‍പ്പടെ എസ്ഐടി റിപ്പോര്‍ട്ടില്‍ ഉള്‍പ്പെടുത്തിയിരുന്നു. അജിത് കുമാര്‍ തങ്ങളെ എഡിജിപി ഓഫീസിലേക്ക് വിളിച്ചു വരുത്തിയെന്നാണ് ഉദ്യോഗസ്ഥരുടെ മൊഴി. റിപ്പോര്‍ട്ട് തിരുത്താന്‍ നിര്‍ദേശിച്ചെന്നും മൊഴിയുണ്ടായിരുന്നു."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'എറണാകുളം', '', '1', 6, 0, '["Kerala","News","Latest"]', 0, 0, 0, '2026, ഒക്ടോ 24 5:59 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (14, '144-580-mvoswi40-zis36', 'തൊഴിലുറപ്പ്: സംസ്ഥാനത്ത് 1.44 കോടി തൊഴിൽദിനങ്ങൾ കുറഞ്ഞു; തൊഴിലാളികൾക്ക് നഷ്ടം 580 കോടി രൂപ', 'കൊല്ലം: മഹാത്മാഗാന്ധി ഗ്രാമീണ തൊഴിലുറപ്പു പദ്ധതിയിൽനിന്ന് വിബി ജി റാം ജിയിലേക്കുള്ള പരിവർത്തനഘട്ടത്തിൽ കഴിഞ്ഞ ആറുമാസത്തിനിടെ സംസ്ഥാനത്ത് 1.44 കോടി തൊഴൽദിനങ്ങളുടെ കുറവ്. 2025-26 സാമ്പത്തികവർഷം ആറുമാസത്തിനിടെ 4,00,83,883 തൊഴിൽദിനങ്ങൾ സൃഷ്ടിച്ച സ്ഥാനത്ത', 'രാഷ്ട്രീയം', '#C8102E', '', '', '2 മിനിറ്റ് വായന', '03:00', '["കൊല്ലം: മഹാത്മാഗാന്ധി ഗ്രാമീണ തൊഴിലുറപ്പു പദ്ധതിയിൽനിന്ന് വിബി ജി റാം ജിയിലേക്കുള്ള പരിവർത്തനഘട്ടത്തിൽ കഴിഞ്ഞ ആറുമാസത്തിനിടെ സംസ്ഥാനത്ത് 1.44 കോടി തൊഴൽദിനങ്ങളുടെ കുറവ്. 2025-26 സാമ്പത്തികവർഷം ആറുമാസത്തിനിടെ 4,00,83,883 തൊഴിൽദിനങ്ങൾ സൃഷ്ടിച്ച സ്ഥാനത്ത്, ഈ സാമ്പത്തികവർഷം സെപ്റ്റംബർവരെ 2,56,21,586 ദിനങങ്ങൾമാത്രമാണ് സംസ്ഥാനത്ത് സൃഷ്ടിക്കാനായത്","1,44,62,297 തൊഴിൽദിനങ്ങൾ കുറഞ്ഞതുവഴി തൊഴിലുറപ്പിൽ പണിയെടുക്കുന്ന സാധാരണ തൊഴിലാളികൾക്ക് 580 കോടിയോളം രൂപയാണ് നഷ്ടപ്പെട്ടത്. തൊഴിൽദിനങ്ങളുടെ കുറവ് പദ്ധതതിയുടെ ലക്ഷ്യങ്ങളെ മാത്രമല്ല, ഗ്രാമീണമേഖലയിലെ സാധാരണ തൊഴിലാളികളുടെ ഉപജീവനത്തെയും ബാധിക്കുന്നു.","കഴിഞ്ഞ ജൂലായ് ഒന്നുമുതലാണ് മഹാത്മാഗാന്ധി ഗ്രാമീണ തൊഴിലുറപ്പു പദ്ധതി നിർത്തലാക്കി, പുതിയ പദ്ധതി ആരംഭിച്ചത്. 40.71 ലക്ഷം കുടുംബങ്ങളിലെ 58.48 ലക്ഷം തൊഴിലലാളികളാണ് സംസ്ഥാനത്ത് പദ്ധതിയിൽ രജിസ്റ്റർ ചെയ്തിട്ടുള്ളത്. ഇതിൽ 17.77 ലക്ഷം കുടുംബങ്ങളിലെ 20.61 ലക്ഷം തൊഴിലാളികൾ പദ്ധതിയെ ആശ്രയിച്ചുകഴിയുന്ന സജീവ തൊഴിലാളികളാണ്.","എന്നാൽ 8.06 ലക്ഷം കുടുംബങ്ങളിലെ 8.63 ലക്ഷം തൊഴിലാളികൾക്കാണ് ഇതുവരെ തൊഴിൽ നൽകാനായത്.ഒരു സാമ്പത്തികവർഷം ഒരു കുടുംബത്തിന് 125 ദിവസം തൊഴിൽ ലഭിക്കുമെന്നാണ് വിബി ജി റാം ജി നിയമത്തിൽ പറയുന്നത്.തൊഴിലിനെത്തിയ കുടുംബങ്ങൾക്ക് സാമ്പത്തികവർഷം പകുതിയായിട്ടും അതിന്റെ അഞ്ചിലൊന്നുപോലും തൊഴിൽദിനങ്ങൾ നൽകാനായില്ലെന്നാണ് കണക്കുകൾ സൂചിപ്പിക്കുന്നത്."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'കൊല്ലം', '', '1', 11, 0, '[]', 0, 0, 0, '2026, ഒക്ടോ 26 10:43 AM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (15, 'news-mvp0sv3a-2n40h', 'മണ്ഡലങ്ങളും സ്ഥാനാർഥികളുമില്ല, വോട്ട് പാർട്ടിക്ക് മാത്രം, ഇസ്രയേലിലെ തിരഞ്ഞെടുപ്പ് രീതി എല്ലാം വ്യത്യസ്തം', 'ഇന്ത്യൻ തെരഞ്ഞെടുപ്പ് പ്രക്രിയയിൽനിന്നു തികച്ചും വ്യത്യസ്തമായ രീതിയാണ് ഇസ്രയേലിൽ.നമ്മുടെ നാട്ടിൽ തെരഞ്ഞെടുപ്പിൽ വോട്ടർമാർ അതതു മണ്ഡലത്തിലെ സ്ഥാനാർഥിക്കാണ് വോട്ട് ചെയ്യുന്നത്. ഏറ്റവും കൂടുതൽ വോട്ട് നേടുന്നയാൾ വിജയിക്കുന്ന ''ഫസ്റ്റ്-പാസ്റ്റ്-ദി-പോസ്റ്റ്', 'ലോകം', '#006b9a', '', '', '1 മിനിറ്റ് വായന', '03:00', '["ഇന്ത്യൻ തെരഞ്ഞെടുപ്പ് പ്രക്രിയയിൽനിന്നു തികച്ചും വ്യത്യസ്തമായ രീതിയാണ് ഇസ്രയേലിൽ.നമ്മുടെ നാട്ടിൽ തെരഞ്ഞെടുപ്പിൽ വോട്ടർമാർ അതതു മണ്ഡലത്തിലെ സ്ഥാനാർഥിക്കാണ് വോട്ട് ചെയ്യുന്നത്. ഏറ്റവും കൂടുതൽ വോട്ട് നേടുന്നയാൾ വിജയിക്കുന്ന ''ഫസ്റ്റ്-പാസ്റ്റ്-ദി-പോസ്റ്റ്'' രീതിയാണിത്.","എന്നാൽ ഇസ്രയേലിൽ ഈ രീതിയല്ല പിന്തുടരുന്നത്. അവിടെ പ്രത്യേക മണ്ഡലങ്ങളില്ല; രാജ്യം മുഴുവൻ ഒറ്റ മണ്ഡലമായാണ് കണക്കാക്കുന്നത്. വോട്ടർമാർ തങ്ങളുടെ പ്രദേശത്തെ ജനപ്രതിനിധിക്കല്ല, മറിച്ച് ഇഷ്ടമുള്ള രാഷ്ട്രീയ പാർട്ടിക്കാണ് വോട്ട് രേഖപ്പെടുത്തുന്നത്. ബാലറ്റ് പേപ്പറിൽ പാർട്ടിയെ പ്രതിനിധീകരിക്കുന്ന ചിഹ്നങ്ങളോ അക്ഷരങ്ങളോ അടയാളപ്പെടുത്തിയാണ് വോട്ടിങ്.","രാജ്യവ്യാപകമായി ഓരോ പാർട്ടിക്കും ലഭിക്കുന്ന വോട്ടിന്റെ ശതമാനത്തിന് ആനുപാതികമായാണ് പാർലമെന്റിലെ സീറ്റുകൾ വീതിച്ചുനൽകുന്നത്. തെരഞ്ഞെടുപ്പിനു മുന്നോടിയായി ഓരോ പാർട്ടിയും മുൻഗണനാക്രമത്തിൽ തങ്ങളുടെ സ്ഥാനാർഥികളുടെ പട്ടിക പ്രസിദ്ധീകരിക്കും. ലഭിക്കുന്ന വോട്ടുകളുടെ എണ്ണത്തിനനുസരിച്ച് ഈ പട്ടികയിൽനിന്ന് ക്രമപ്രകാരം സ്ഥാനാർഥികൾ പാർലമെന്റിലെത്തും."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'അന്തർദേശീയം', '', '1', 7, 0, '[]', 0, 0, 0, '2026, ഒക്‌ടോബർ 26 02:24 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (16, 'news-mvp12rzq-zpvey', '‘സുഹൈൽ മദ്യപിച്ച് വണ്ടിയോടിച്ചു, സ്കൂട്ടറിലിടിച്ച് മൂന്നുപേർ മരിച്ചു, പേടിച്ച് വിറച്ചുപോയി’; കുരുക്കായി ഓഡിയോ സന്ദേശം', 'കൊച്ചി: നെടുമ്പാശ്ശേരിയിൽ മൂന്നുപേർ കൊല്ലപ്പെട്ട വാഹനാപകടക്കേസിൽ പ്രതി സുഹൈൽ സജീവിന് കുരുക്കായി ശബ്ദരേഖ. സുഹൃത്തായ ജോയൽ തന്റെ ഫോണിൽ അയച്ച ശബ്ദരേഖ തെളിവായി പോലീസ് കോടതിയിൽ സമർപ്പിച്ചു. പ്രതികളുടെ ജാമ്യം എതിർത്തുകൊണ്ടാണ് പോലീസ് തെളിവുകൾ സമർപ്പിച്ചത്. ക', 'പ്രത്യേക റിപ്പോർട്ട്', '#991b1b', 'https://img.mathrubhumi.com/view/acePublic/alias/contentid/1up1k12emnboy5xgx1r/0/suhail-minicooper-accident.webp?f=3%3A2&q=0.75&w=900', 'മുഖ്യപ്രതി സുഹൈലിനെ പോലീസ് വാഹനത്തിൽ നെടുമ്പാശ്ശേരി എയർപോർട്ട് റോഡിൽ തെളിവെടുപ്പിന് എത്തിച്ചപ്പോൾ, പ്രതികളായ സുഹൈൽ, നിനവ്, ജോയൽ, അമീൻ എന്നിവരെ മെഡിക്കൽ പരിശോധനയ്ക്കായി അങ്കമാലി താലൂക്ക് ആശുപത്രിയിൽ കൊണ്ടുവന്നപ്പോൾ', '2 മിനിറ്റ് വായന', '03:00', '["കൊച്ചി: നെടുമ്പാശ്ശേരിയിൽ മൂന്നുപേർ കൊല്ലപ്പെട്ട വാഹനാപകടക്കേസിൽ പ്രതി സുഹൈൽ സജീവിന് കുരുക്കായി ശബ്ദരേഖ. സുഹൃത്തായ ജോയൽ തന്റെ ഫോണിൽ അയച്ച ശബ്ദരേഖ തെളിവായി പോലീസ് കോടതിയിൽ സമർപ്പിച്ചു. പ്രതികളുടെ ജാമ്യം എതിർത്തുകൊണ്ടാണ് പോലീസ് തെളിവുകൾ സമർപ്പിച്ചത്. കേസിലെ മൂന്നാം പ്രതിയാണ് ജോയൽ. അപകടസമയത്ത് ജോയലും മിനി കൂപ്പർ കാറിലുണ്ടായിരുന്നു.","സുഹൈൽ മദ്യപിച്ച് അമിതവേഗതയിൽ വാഹനമോടിച്ചു. വരുന്ന വഴിക്ക് കാർ സ്‌കൂട്ടറിൽ ഇടിച്ചുതെറിപ്പിച്ചു. മൂന്നുപേർ മരിച്ചു. പേടിച്ച് വിറച്ചുപോയി, ഞങ്ങൾ സ്ഥലത്ത് നിന്ന് രക്ഷപ്പെട്ടു. നാട്ടുകാരെത്തിയപ്പോൾ സുഹൈൽ വാപ്പ നോക്കുമെന്ന് പറഞ്ഞതായും പോലീസ് ഫോണിൽ കണ്ടെത്തിയ ശബ്ദരേഖയിലുണ്ട്.പ്രതികളുടെ ജാമ്യാപേക്ഷയിൽ സെഷൻസ് കോടതിയിൽ വാദം തുടരുകയാണ്. പ്രതിക്ക് ജാമ്യം അനുവദിക്കുന്നത് സമൂഹത്തിന് തെറ്റായ സന്ദേശം നൽകുമെന്ന് പോലീസ് കോടതിയിൽ അറിയിച്ചിട്ടുണ്ട്. പ്രതി സ്ഥിരമായി അമിതവേഗതയിൽ വാഹനമോടിക്കുന്നതിന്റെ തെളിവുകൾ ലഭിച്ചിട്ടുണ്ട്. മൂന്ന് പേർ മരിച്ച കാര്യം പ്രതികൾ സുഹൃത്തിനെ അറിയിച്ചു. സുഹൈൽ ആദ്യം വിളിച്ചത് പിതാവിനെയാണ് തുടങ്ങിയ കാര്യങ്ങളും പോലീസ് കോടതിയെ അറിയിച്ചിട്ടുണ്ട്.","അതേസമയം എഫ്.ഐ.ആറിൽ പ്രതികളുടെ പേര് പറയുന്നില്ല. തെളിവില്ലാതെയാണ് നരഹത്യാക്കുറ്റം ചുമത്തിയത്. കേസിന്റെ ക്ലൈമാക്‌സ് നേരത്തെ തീരുമാനിച്ചിരുന്നു തുടങ്ങിയ വാദങ്ങളാണ് പ്രതിഭാഗത്തിന് വേണ്ടി ഹാജരായ അഭിഭാഷകർ വാദിച്ചത്. നേരത്തെ അങ്കമാലി മജിസ്ട്രേറ്റ് കോടതി പ്രതികളുടെ ജാമ്യാപേക്ഷ തള്ളിയത്. തുടർന്നാണ് പ്രതികൾ ജാമ്യാപേക്ഷയുമായി സെഷൻസ് കോടതിയെ സമീപിച്ചത്. ജാമ്യാപേക്ഷയിൽ വാദം തുടരുകയാണ്."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'എറണാകുളം', '', '1', 7, 0, '[]', 0, 0, 0, '2026, ഒക്‌ടോബർ 26 02:32 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (17, 'news-mvp18bvq-cakb9', 'ഒരു റണ്ണകലെ ദേവ്ദത്തിന് ഇരട്ട സെഞ്ചുറി നഷ്ടമായി; ന്യൂസീലൻഡ് എയ്‌ക്കെതിരെ ഇന്ത്യയുടെ തിരിച്ചുവരവ്', 'ലിങ്കൺ: ന്യൂസീലൻഡ് എ ടീമിനെതിരായ അനൗദ്യോഗിക ടെസ്റ്റിന്റെ മൂന്നാം ദിനം ഇന്ത്യ മികച്ച നിലയിൽ. മൂന്നാം ദിനം കളി നിർത്തുമ്പോൾ ഇന്ത്യ എട്ട് വിക്കറ്റ് നഷ്ടത്തിൽ 288 റൺസ് എന്ന നിലയിലാണ്. നിലവിൽ ഇന്ത്യ എക്ക് 284 റൺസ് ലീഡുണ്ട്. 51 റൺസോടെ വാഷിങ്ടൺ സുന്ദറും ഒരു', 'സ്പോർട്സ്', '#15803d', 'https://img.mathrubhumi.com/view/acePublic/alias/contentid/1up0odzkz1x2xqcz58q/0/devdutt-padikkal-jpg.webp?f=3%3A2&q=0.75&w=900', '', '2 മിനിറ്റ് വായന', '03:00', '["ലിങ്കൺ: ന്യൂസീലൻഡ് എ ടീമിനെതിരായ അനൗദ്യോഗിക ടെസ്റ്റിന്റെ മൂന്നാം ദിനം ഇന്ത്യ മികച്ച നിലയിൽ. മൂന്നാം ദിനം കളി നിർത്തുമ്പോൾ ഇന്ത്യ എട്ട് വിക്കറ്റ് നഷ്ടത്തിൽ 288 റൺസ് എന്ന നിലയിലാണ്. നിലവിൽ ഇന്ത്യ എക്ക് 284 റൺസ് ലീഡുണ്ട്. 51 റൺസോടെ വാഷിങ്ടൺ സുന്ദറും ഒരു പന്തുമാത്രം നേരിട്ട ആകാശ് ദീപുമാണ് ക്രീസിൽ.മലയാളി താരം ദേവ്ദത്ത് പടിക്കലിന്റെ സെഞ്ചുറിയും സായ് സുദർശൻ, യാഷ് റാത്തോഡ് എന്നിവരുടെ അർധ സെഞ്ചുറികളുമാണ് ഇന്ത്യ എക്ക് മികച്ച സ്‌കോർ സമ്മാനിച്ചത്. മൂന്നാം ദിനം 56 റൺസിൽ നിന്ന് തുടങ്ങിയ ദേവ്ദത്ത് കിവീസ് ബൗളർമാരെ കടന്നാക്രമിച്ചു. ഇരട്ട സെഞ്ചുറിക്ക് ഒരു റൺ അരികെ സാക്ക് ഗിബ്‌സണിന്റെ പന്തിൽ ഔട്ടായി. 248 പന്തിൽ 24 ഫോറും മൂന്ന് സിക്‌സും സഹിതമാണ് ദേവ്ദത്ത് 199 റൺസ് അടിച്ചെടുത്തത്.","സായ് സുദർശൻ 184 പന്തിൽ നിന്ന് 91 റൺസ് നേടി. 72 പന്തിൽ നിന്ന് 66 റൺസുമായി യാഷ് റാത്തോഡും പിന്തുണ നൽകി. രണ്ടാം ദിനം ആദ്യ അഞ്ച് ഓവറിനുള്ളിൽതന്നെ ഓപ്പണർമാരായ കെ.എൽ രാഹുലിനേയും യശസ്വി ജയ്‌സ്വാളിനേയും നഷ്ടപ്പെട്ട് തകർച്ചയിലായ ഇന്ത്യ എയെ ദേവ്ദത്തും സായ് സുദർശനും ചേർന്നാണ് കരകയറ്റിയത്. ഇരുവരും മൂന്നാം വിക്കറ്റിൽ 215 റൺസ് കൂട്ടുകെട്ടുണ്ടാക്കി.നേരത്തെ ഒന്നാം ഇന്നിങ്‌സിൽ ഇന്ത്യ 113 റൺസിന് പുറത്തായിരുന്നു. മറുപടി ബാറ്റിങ്ങിൽ ന്യൂസീലൻഡ് എ 317 റൺസ് അടിച്ചെടുക്കുകയും ചെയ്തു."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'ദേശീയം', '', '1', 51, 0, '[]', 0, 0, 0, '2026, ഒക്‌ടോബർ 26 02:36 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (18, 'news-mvqdfv6k-hi2qh', 'ചേരാനല്ലൂർ വാഹനാപകടം: പൊലീസിന്റെ വീഴ്ച പരിശോധിക്കും; എഡിജിപി ജയബാലകൃഷ്ണന്റെ കുടുംബത്തെ കാണും', 'കൊച്ചി ∙ ചേരാനല്ലൂർ വാഹനാപകട വിഷയം കൈകാര്യം ചെയ്തതിൽ വീഴ്ച സംഭവിച്ചുവെന്ന് ആഭ്യന്തരമന്ത്രി രമേശ് ചെന്നിത്തല തന്നെ വ്യക്തമാക്കിയ സാഹചര്യത്തിൽ നടപടികളുമായി പൊലീസ് നേതൃത്വം. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്നു പരിശോധിക്കുന്നതിന്  ചേരാനല്ലൂർ സ്റ്റേഷനിലെത്തി.', 'KERALA', '#C8102E', 'https://img-mm.manoramaonline.com/content/dam/mm/mo/archive/news/just-in/images/2026/10/27/adgp-p-vijayan-chernalloor-accident.jpg?w=1120&h=583', 'എഡിജിപി പി.വിജയൻ ചേരാനല്ലൂരിൽ അപകടമുണ്ടായ സ്ഥലത്ത്.', '2 മിനിറ്റ് വായന', '03:00', '["കൊച്ചി ∙ ചേരാനല്ലൂർ വാഹനാപകട വിഷയം കൈകാര്യം ചെയ്തതിൽ വീഴ്ച സംഭവിച്ചുവെന്ന് ആഭ്യന്തരമന്ത്രി രമേശ് ചെന്നിത്തല തന്നെ വ്യക്തമാക്കിയ സാഹചര്യത്തിൽ നടപടികളുമായി പൊലീസ് നേതൃത്വം. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്നു പരിശോധിക്കുന്നതിന്  ചേരാനല്ലൂർ സ്റ്റേഷനിലെത്തി. കൊച്ചി സിറ്റി പൊലീസ് കമ്മിഷണർ കാളിരാജ് മഹേഷ് കുമാർ അടക്കം ജില്ലയിലെ ക്രമസമാധാന ചുമതലയുള്ള പൊലീസ് ഉദ്യോഗസ്ഥർ മുഴുവൻ നിലവിൽ ചേരാനല്ലൂർ സ്റ്റേഷനിലുണ്ട്. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്ന് പരിശോധിക്കുമെന്നും ബന്ധപ്പെട്ട എല്ലാവരുമായും കൂടിക്കാഴ്ച നടത്തുമെന്നും പി.വിജയൻ മാധ്യമങ്ങളോട് പറ‍ഞ്ഞു.","കൊല്ലപ്പെട്ട ജയബാലകൃഷ്ണന്റെ കുടുംബവുമായി എഡിജിപി ഇന്ന് കൂടിക്കാഴ്ച നടത്തും. വാഹനത്തിന്റെ ആർസി ഓണറായ ജഡ്ജിയെ സസ്പെൻഡ് ചെയ്യുക, പ്രതിയുടെ ജാമ്യം റദ്ദാക്കുക, തങ്ങളോട് മോശമായി പെരുമാറിയ ഉദ്യോഗസ്ഥർക്കെതിരെ നടപടിയെക്കുക എന്നീ കാര്യങ്ങളാണ് കുടുംബം ആവശ്യപ്പെടുന്നത്. ഇന്നു വൈകിട്ട് 4 മണിക്ക് മുൻപ് ഇക്കാര്യങ്ങളിൽ തീരുമാനമുണ്ടാകണമെന്നും ഇല്ലെങ്കിൽ വീണ്ടും പൊലീസ് സ്റ്റേഷനു മുന്നിൽ സമരം തുടങ്ങുമെന്നും കുടുംബം വ്യക്തമാക്കിയിരുന്നു. വിഷയത്തിൽ വീഴ്ച വരുത്തിയ പൊലീസ് ഉദ്യോഗസ്ഥർക്കെതിരെ ഇന്നു തന്നെ നടപടി ഉണ്ടായേക്കുമെന്നാണ് വിവരം. പ്രതിയെ സ്റ്റേഷൻ ജാമ്യത്തിൽ വിട്ടയച്ച പൊലീസ് നടപടിയിൽ ആഭ്യന്തര മന്ത്രി കടുത്ത അമർഷം അറിയിച്ചിരുന്നു. ഇതിനു പിന്നാലെയാണ് എഡിജിപി പി.വിജയനെ കുടുംബത്തെ കാണുന്നതിനും പൊലീസിന്റെ വീഴ്ചകൾ പരിശോധിക്കുന്നതിനുമായി നിയോഗിച്ചത്.","അതേ സമയം, അപകടത്തിന് കാരണമായ വാഹനത്തിന്റെ ഉടമയായ അഡിഷനൽ ജില്ലാ ജഡ്ജിയെ ഇന്നു തന്നെ സസ്പെൻഡ് ചെയ്യാനും സാധ്യതയുണ്ട്. തൃശൂർ ജില്ലയുടെ ചുമതലയുള്ള ജസ്റ്റിസ് പി.വി.കുഞ്ഞികൃഷ്ണൻ ഇതു സംബന്ധിച്ച് ഇന്നലെ തന്നെ ചീഫ് ജസ്റ്റിസിനും ഹൈക്കോടതി റജിസ്ട്രാർക്കും റിപ്പോർട്ട് നൽകിയിരുന്നു. ഹൈക്കോടതി അഡ്മിനിസസ്ട്രേറ്റീവ് കമ്മിറ്റി ചേർന്നായിരിക്കും ജഡ്ജിയുടെ വിഷയം പരിശോധിക്കുക."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'എറണാകുളം', '', '1', 1, 0, '[]', 0, 0, 0, '2026, ഒക്‌ടോബർ 27 01:05 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (19, 'news-mvqdg0k2-r8qkl', 'ചേരാനല്ലൂർ വാഹനാപകടം: പൊലീസിന്റെ വീഴ്ച പരിശോധിക്കും; എഡിജിപി ജയബാലകൃഷ്ണന്റെ കുടുംബത്തെ കാണും', 'കൊച്ചി ∙ ചേരാനല്ലൂർ വാഹനാപകട വിഷയം കൈകാര്യം ചെയ്തതിൽ വീഴ്ച സംഭവിച്ചുവെന്ന് ആഭ്യന്തരമന്ത്രി രമേശ് ചെന്നിത്തല തന്നെ വ്യക്തമാക്കിയ സാഹചര്യത്തിൽ നടപടികളുമായി പൊലീസ് നേതൃത്വം. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്നു പരിശോധിക്കുന്നതിന്  ചേരാനല്ലൂർ സ്റ്റേഷനിലെത്തി.', 'KERALA', '#C8102E', 'https://img-mm.manoramaonline.com/content/dam/mm/mo/archive/news/just-in/images/2026/10/27/adgp-p-vijayan-chernalloor-accident.jpg?w=1120&h=583', 'എഡിജിപി പി.വിജയൻ ചേരാനല്ലൂരിൽ അപകടമുണ്ടായ സ്ഥലത്ത്.', '2 മിനിറ്റ് വായന', '03:00', '["കൊച്ചി ∙ ചേരാനല്ലൂർ വാഹനാപകട വിഷയം കൈകാര്യം ചെയ്തതിൽ വീഴ്ച സംഭവിച്ചുവെന്ന് ആഭ്യന്തരമന്ത്രി രമേശ് ചെന്നിത്തല തന്നെ വ്യക്തമാക്കിയ സാഹചര്യത്തിൽ നടപടികളുമായി പൊലീസ് നേതൃത്വം. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്നു പരിശോധിക്കുന്നതിന്  ചേരാനല്ലൂർ സ്റ്റേഷനിലെത്തി. കൊച്ചി സിറ്റി പൊലീസ് കമ്മിഷണർ കാളിരാജ് മഹേഷ് കുമാർ അടക്കം ജില്ലയിലെ ക്രമസമാധാന ചുമതലയുള്ള പൊലീസ് ഉദ്യോഗസ്ഥർ മുഴുവൻ നിലവിൽ ചേരാനല്ലൂർ സ്റ്റേഷനിലുണ്ട്. പൊലീസിന് വീഴ്ചയുണ്ടായോ എന്ന് പരിശോധിക്കുമെന്നും ബന്ധപ്പെട്ട എല്ലാവരുമായും കൂടിക്കാഴ്ച നടത്തുമെന്നും പി.വിജയൻ മാധ്യമങ്ങളോട് പറ‍ഞ്ഞു.","കൊല്ലപ്പെട്ട ജയബാലകൃഷ്ണന്റെ കുടുംബവുമായി എഡിജിപി ഇന്ന് കൂടിക്കാഴ്ച നടത്തും. വാഹനത്തിന്റെ ആർസി ഓണറായ ജഡ്ജിയെ സസ്പെൻഡ് ചെയ്യുക, പ്രതിയുടെ ജാമ്യം റദ്ദാക്കുക, തങ്ങളോട് മോശമായി പെരുമാറിയ ഉദ്യോഗസ്ഥർക്കെതിരെ നടപടിയെക്കുക എന്നീ കാര്യങ്ങളാണ് കുടുംബം ആവശ്യപ്പെടുന്നത്. ഇന്നു വൈകിട്ട് 4 മണിക്ക് മുൻപ് ഇക്കാര്യങ്ങളിൽ തീരുമാനമുണ്ടാകണമെന്നും ഇല്ലെങ്കിൽ വീണ്ടും പൊലീസ് സ്റ്റേഷനു മുന്നിൽ സമരം തുടങ്ങുമെന്നും കുടുംബം വ്യക്തമാക്കിയിരുന്നു. വിഷയത്തിൽ വീഴ്ച വരുത്തിയ പൊലീസ് ഉദ്യോഗസ്ഥർക്കെതിരെ ഇന്നു തന്നെ നടപടി ഉണ്ടായേക്കുമെന്നാണ് വിവരം. പ്രതിയെ സ്റ്റേഷൻ ജാമ്യത്തിൽ വിട്ടയച്ച പൊലീസ് നടപടിയിൽ ആഭ്യന്തര മന്ത്രി കടുത്ത അമർഷം അറിയിച്ചിരുന്നു. ഇതിനു പിന്നാലെയാണ് എഡിജിപി പി.വിജയനെ കുടുംബത്തെ കാണുന്നതിനും പൊലീസിന്റെ വീഴ്ചകൾ പരിശോധിക്കുന്നതിനുമായി നിയോഗിച്ചത്.","അതേ സമയം, അപകടത്തിന് കാരണമായ വാഹനത്തിന്റെ ഉടമയായ അഡിഷനൽ ജില്ലാ ജഡ്ജിയെ ഇന്നു തന്നെ സസ്പെൻഡ് ചെയ്യാനും സാധ്യതയുണ്ട്. തൃശൂർ ജില്ലയുടെ ചുമതലയുള്ള ജസ്റ്റിസ് പി.വി.കുഞ്ഞികൃഷ്ണൻ ഇതു സംബന്ധിച്ച് ഇന്നലെ തന്നെ ചീഫ് ജസ്റ്റിസിനും ഹൈക്കോടതി റജിസ്ട്രാർക്കും റിപ്പോർട്ട് നൽകിയിരുന്നു. ഹൈക്കോടതി അഡ്മിനിസസ്ട്രേറ്റീവ് കമ്മിറ്റി ചേർന്നായിരിക്കും ജഡ്ജിയുടെ വിഷയം പരിശോധിക്കുക."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'എറണാകുളം', '', '43', 42, 2, '[]', 0, 0, 1, '2026, ഒക്‌ടോബർ 27 01:06 PM', '2026-10-31 12:46:04');
INSERT INTO `articles` (`id`, `custom_id`, `title`, `lead`, `category`, `category_color`, `image_url`, `image_caption`, `read_time`, `audio_duration`, `paragraphs`, `highlights`, `author_name`, `author_designation`, `author_location`, `author_avatar`, `author_verified`, `district`, `country`, `views`, `views_count`, `likes_count`, `tags`, `is_breaking`, `is_trending`, `is_headline`, `published_at`, `created_at`) VALUES (20, '1-22-mvqf2ex3-7dcdz', 'ഒരു കിലോഗ്രാമിന് 1 കോടി രൂപയിൽ അധികം വില; വലയിൽ കയറിയാൽ കളയും; 22 കോടി വില വരുന്ന തിമിംഗല ദഹനശിഷ്ടം കിട്ടിയത് കള്ളനോട്ട് കേസിലെ പ്രതിയുടെ ലോക്കറിൽ നിന്ന്', 'കൊല്ലം ∙ കള്ളനോട്ട് കേസിലെ പ്രതിയുടെ ലോക്കർ റൂമിൽ നിന്നു തിമിംഗല ദഹനശിഷ്ടം (ആംബർഗ്രിസ്) പിടികൂടിയ കേസ് വനം വകുപ്പിനു കൈമാറി. പൊലീസ് പിടികൂടിയ 22 കോടിയിലധികം രൂപ വില വരുന്ന 22.5 കിലോഗ്രാം തിമിംഗല ദഹനശിഷ്ടം വനം വകുപ്പ് ഏറ്റെടുത്തു. കഴിഞ്ഞ ദിവസം രാത്രി', 'KERALA', '#C8102E', 'https://img-mm.manoramaonline.com/content/dam/mm/mo/district-news/kollam/images/2026/10/27/Whale-story-local-news.jpg?w=720&h=375', 'പിടിച്ചെടുത്ത തിമിംഗല ദഹന  ശിഷ്ടം.', '3 മിനിറ്റ് വായന', '03:00', '["കൊല്ലം ∙ കള്ളനോട്ട് കേസിലെ പ്രതിയുടെ ലോക്കർ റൂമിൽ നിന്നു തിമിംഗല ദഹനശിഷ്ടം (ആംബർഗ്രിസ്) പിടികൂടിയ കേസ് വനം വകുപ്പിനു കൈമാറി. പൊലീസ് പിടികൂടിയ 22 കോടിയിലധികം രൂപ വില വരുന്ന 22.5 കിലോഗ്രാം തിമിംഗല ദഹനശിഷ്ടം വനം വകുപ്പ് ഏറ്റെടുത്തു. കഴിഞ്ഞ ദിവസം രാത്രി നടത്തിയ പരിശോധനയിൽ കൊല്ലം തങ്കശ്ശേരി ഹാർബറിൽ ഹാർബർ എൻജിനീയറിങ് വിഭാഗം മത്സ്യബന്ധന ബോട്ട് ഉടമകൾക്കായി വാടകയ്ക്കു നൽകുന്ന തങ്കശ്ശേരി അഞ്ചാം ബ്ലോക്കിലെ പത്താം നമ്പർ ലോക്കർ റൂമിൽ നിന്നാണു തിമിംഗല ദഹനശിഷ്ടം കണ്ടെത്തിയത്.ഈ റൂം കള്ളനോട്ട് കേസിലെ പ്രതിയായ കൊല്ലം വെസ്റ്റ് കൈക്കുളങ്ങര വാടി കല്ലേലിവയലിൽ സിബിയോൺ വാടകയ്ക്ക് എടുത്തിരുന്നതാണ്. സിബിയോൺ രഹസ്യകേന്ദ്രത്തിൽ തിമിംഗല ദഹനശിഷ്ടം സൂക്ഷിച്ചിട്ടുണ്ടെന്ന രഹസ്യ വിവരം കള്ളനോട്ട് കേസിൽ അറസ്റ്റിലായപ്പോഴാണു പൊലീസിനു ലഭിച്ചത്. ആംബർഗ്രിസ് കൈവശം വച്ച സംഭവം അഞ്ചൽ റേഞ്ച് ഓഫിസ് കേസ് റജിസ്റ്റർ ചെയ്ത് അന്വേഷണം ആരംഭിച്ചതായി വനം വകുപ്പ് ഉദ്യോഗസ്ഥർ പറഞ്ഞു. ചെന്നൈയിലെ ലാബിലേക്ക് തിമിംഗല ദഹനശിഷ്ടം അയയ്ക്കാനായി കോടതിയുടെ അനുമതി വാങ്ങും. ലാബ് റിപ്പോർട്ടിന്റെ അടിസ്ഥാനത്തിൽ തുടർ നടപടികൾ സ്വീകരിക്കും. ആംബർഗ്രിസ് കേസിൽ മറ്റുള്ളവർക്ക് പങ്കുണ്ടുണ്ടോയെന്നതും അന്വേഷിക്കുന്നുണ്ട്.","ഒരു കിലോഗ്രാമിന് 1 കോടി രൂപയിൽ അധികമാണ് വില. ഇവ കൈവശം സൂക്ഷിക്കുന്നത് നിയമവിരുദ്ധമാണ്. ആംബർഗ്രിസ് കൈവശം സൂക്ഷിക്കുന്ന കേസിൽ 7 വർഷം തടവോ 25,000 രൂപ പിഴയോ അല്ലെങ്കിൽ ഇവ രണ്ടും ഒരുമിച്ചോ അനുഭവിക്കണം.തിമിംഗലങ്ങൾ കഴിയുന്ന ആഴക്കടലിലാണ് ആംബർഗ്രിസ് കൂടുതലായും കാണാറുള്ളതെന്നും അപൂർവമായി കരയ്ക്കു സമീപത്തും ഇവ കണ്ടെത്തിയിട്ടുണ്ടെന്നും മത്സ്യത്തൊഴിലാളികൾ പറയുന്നു. വെള്ളത്തിനു മുകളിൽ പാളി പോലെയാണ് ഇവ കാണാറുള്ളത്. മത്സ്യത്തൊഴിലാളികൾ ഇവ ശേഖരിക്കുകയോ കരയിലേക്കു കൊണ്ടുവരികയോ ചെയ്യാറില്ല. അപൂർവമായി ആഴക്കടൽ മത്സ്യബന്ധനം നടത്തുന്നതിനിടെ ഇവ അബദ്ധത്തിൽ വലയിൽ കയറിയാൽ, ഉടനെ എടുത്തു കടലിൽ കളയും. എന്നാൽ, കരയോടു ചേർന്നുള്ള പ്രദേശങ്ങളിൽനിന്ന് ഇവ ലഭിച്ചാൽ വനംവകുപ്പിനെ വിവരം അറിയിച്ച് ഇവ അവർക്കു കൈമാറുമെന്ന് മത്സ്യത്തൊഴിലാളികൾ പറയുന്നു.നിലവിൽ വനം വകുപ്പ് ഏറ്റെടുത്ത തിമിംഗല ദഹനശിഷ്ടം വിദഗ്ധ പരിശോധനയ്ക്കായി തിരുവനന്തപുരത്തെ ബയോടെക്നോളജി ലാബിലേക്ക് അയച്ചിട്ടുണ്ട്. ഇവിടെ വിവിധ തലങ്ങളിൽ നടത്തുന്ന പരിശോധനകൾക്കു ശേഷമാണ്, പിടികൂടിയതു തിമിംഗല ദഹനശിഷ്ടമാണെന്ന് ഔദ്യോഗികമായി ഉറപ്പാക്കാൻ സാധിക്കുക. തിമിംഗല ദഹനശിഷ്ടത്തിന്റെ ക്വാളിറ്റിയും ഇതിനുശേഷം മാത്രമേ കണ്ടെത്താൻ സാധിക്കൂവെന്ന് ഉദ്യോഗസ്ഥർ‌ പറഞ്ഞു.","എണ്ണത്തിമിംഗലം എന്നറിയപ്പെടുന്ന സ്പേം തിമിംഗലങ്ങളുടെ വയറ്റിൽ രൂപപ്പെടുന്ന മെഴുക് പോലെയുള്ള വസ്തുവാണ് ആംബർഗ്രിസ്. തിമിംഗലങ്ങൾ കഴിക്കുന്ന മറ്റു മത്സ്യങ്ങളുടെയും ജീവികളുടെയും ദഹിക്കാത്ത ഭാഗങ്ങൾ സംരക്ഷിക്കാനായി കുടലിൽ ഉണ്ടാകുന്ന സ്രവമാണിത്. ഇത് പിന്നീട് ഛർദിയിലൂടെയോ വിസർജ്യത്തിലൂടെയോ തിമിംഗലം പുറത്തേക്കു തള്ളും. സുഗന്ധ ദ്രവ്യങ്ങളുടെ മണം കൂടുതൽ നേരം നിലനിൽക്കാൻ സഹായിക്കുന്ന ഫിക്സേറ്റിവ് ആയാണ് ഇത് പ്രധാനമായും ഉപയോഗിക്കുന്നത്."]', '[]', 'എഡിറ്റർ', 'എഡിറ്റർ', 'കേരളം', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=400&q=80', 1, 'കൊല്ലം', '', '1', 13, 0, '[]', 0, 0, 0, '2026, ഒക്‌ടോബർ 27 01:51 PM', '2026-10-31 12:46:04');

DROP TABLE IF EXISTS `breaking_news`;
CREATE TABLE `breaking_news` (
  `id` int NOT NULL AUTO_INCREMENT,
  `headline` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` tinyint(1) DEFAULT '1',
  `priority` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for breaking_news
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (1, 'വയനാട് തുരങ്കപാത നിർമാണത്തിന് കേന്ദ്ര പരിസ്ഥിതി അനുമതി ലഭിച്ചു; ടെൻഡർ നടപടികൾ വേഗത്തിലാക്കാൻ നിർദേശം', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (2, 'സംസ്ഥാനത്ത് വേനൽമഴ ശക്തമാകാൻ സാധ്യത: തെക്കൻ ജില്ലകളിൽ യെല്ലോ അലർട്ട് പ്രഖ്യാപിച്ചു', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (3, 'തിരുവനന്തപുരം മെട്രോ പദ്ധതിയുടെ പുതുക്കിയ ഡിപിആർ കേന്ദ്രാനുമതിക്കായി സമർപ്പിച്ചു', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (4, 'ഗൾഫ് രാജ്യങ്ങളിൽ പെരുന്നാൾ അവധി പ്രഖ്യാപിച്ചു: യുഎഇയിൽ 4 ദിവസത്തെ ശമ്പളത്തോടുകൂടിയ അവധി', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (5, 'കൊച്ചി മെട്രോ കാക്കനാട് പാത നിർമാണം 70% പൂർത്തിയായി: ഡിസംബറിൽ ട്രയൽ റൺ', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (6, 'ഖത്തര്‍ KMCC കവര്‍ച്ചയില്‍ ആദ്യ നടപടി; വ്യവസായി റസാഖ് റൊട്ടാനയെ പുറത്താക്കി മുസ്‌ലിം ലീഗ്', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (7, 'തൊഴിലുറപ്പ്: സംസ്ഥാനത്ത് 1.44 കോടി തൊഴിൽദിനങ്ങൾ കുറഞ്ഞു; തൊഴിലാളികൾക്ക് നഷ്ടം 580 കോടി രൂപ', 1, 0, '2026-10-31 12:46:04');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (8, 'ചേരാനല്ലൂർ വാഹനാപകടം: പൊലീസിന്റെ വീഴ്ച പരിശോധിക്കും; എഡിജിപി ജയബാലകൃഷ്ണന്റെ കുടുംബത്തെ കാണും', 1, 0, '2026-10-31 12:46:04');
