INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (10, 'വയനാട് തുരങ്കപാത നിർമാണത്തിന് കേന്ദ്ര പരിസ്ഥിതി അനുമതി ലഭിച്ചു; ടെൻഡർ നടപടികൾ വേഗത്തിലാക്കാൻ നിർദേശം', 1, 0, '2026-10-31 12:47:22');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (11, 'സംസ്ഥാനത്ത് വേനൽമഴ ശക്തമാകാൻ സാധ്യത: തെക്കൻ ജില്ലകളിൽ യെല്ലോ അലർട്ട് പ്രഖ്യാപിച്ചു', 1, 0, '2026-10-31 12:47:22');
INSERT INTO `breaking_news` (`id`, `headline`, `active`, `priority`, `created_at`) VALUES (12, 'തിരുവനന്തപുരം മെട്രോ പദ്ധതിയുടെ പുതുക്കിയ ഡിപിആർ കേന്ദ്രാനുമതിക്കായി സമർപ്പിച്ചു', 1, 0, '2026-10-31 12:47:22');
