DROP TABLE IF EXISTS `videos`;
CREATE TABLE `videos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `video_url` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `youtube_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'വാർത്തകൾ',
  `duration` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '02:30',
  `views_count` int DEFAULT '100',
  `thumbnail` text COLLATE utf8mb4_unicode_ci,
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for videos
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (1, 'സൗദി ഗോൾഡൻ റെസിഡൻസി: പ്രവാസികൾ അറിഞ്ഞിരിക്കേണ്ട 5 മാറ്റങ്ങൾ', 'https://www.youtube.com/watch?v=0U17y9a2q3w', '0U17y9a2q3w', 'PRAVASI', '03:15', 510000, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=600&q=80', 'സൗദി അറേബ്യ പ്രഖ്യാപിച്ച പുതിയ പ്രീമിയം റെസിഡൻസി നിബന്ധനകൾ.', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (2, 'വയനാട് തുരങ്കപാത: റൂട്ട് മാപ്പും 3D ആകാശ ദൃശ്യങ്ങളും പുറത്ത്', 'https://www.youtube.com/watch?v=0U17y9a2q3w', '0U17y9a2q3w', 'DEVELOPMENT', '01:45', 420000, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=600&q=80', 'വയനാട് ആനക്കാംപൊയിൽ-കള്ളാടി-മേപ്പാടി ഇരട്ട തുരങ്കപാത റൂട്ട് മാപ്പും 3D ദൃശ്യങ്ങളും.', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (3, 'മെട്രോ പുതിയ പാത കാക്കനാട്: ട്രയൽ റൺ തത്സമയം കാണാം', 'https://www.youtube.com/watch?v=Ko18SgHA43I', 'Ko18SgHA43I', 'METRO', '02:10', 285000, 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=600&q=80', 'കൊച്ചി മെട്രോ രണ്ടാം ഘട്ട കാക്കനാട് പാത നിർമാണ പുരോഗതിയും ട്രയൽ റണ്ണും.', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (4, 'വേനൽമഴ ശക്തമാകുന്നു: തെക്കൻ ജില്ലകളിൽ അതീവ ജാഗ്രതാ നിർദ്ദേശം', 'https://www.youtube.com/watch?v=Ko18SgHA43I', 'Ko18SgHA43I', 'WEATHER', '01:20', 190000, 'https://images.unsplash.com/photo-1534274988757-a28bf1a57c17?auto=format&fit=crop&w=600&q=80', 'കാലാവസ്ഥാ നിരീക്ഷണ കേന്ദ്രത്തിന്റെ ഏറ്റവും പുതിയ മഴ മുന്നറിയിപ്പ്.', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (5, 'പ്രായപൂർത്തിയാകാത്ത മകന് വാഹനം ഓടിക്കാൻ നൽകി; ചേരാനല്ലൂർ വാഹനാപകടത്തിൽ പിതാവിനെതിരെ കേസ്', 'https://youtu.be/dXpuzlD21g0', 'dXpuzlD21g0', 'KERALA', '01:30', 1200, 'https://img.youtube.com/vi/dXpuzlD21g0/hqdefault.jpg', '', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (6, 'ഗൾഫ് മേഖല സമാധാന തീരത്തേക്കോ?; നെതന്യാഹുവും സൈന്യവും നേർക്കുനേർ', 'https://youtu.be/vCHI7ucVRKM', 'vCHI7ucVRKM', 'PRAVASI', '01:30', 1200, 'https://youtu.be/vCHI7ucVRKM', '', '2026-10-31 12:47:35');
INSERT INTO `videos` (`id`, `title`, `video_url`, `youtube_id`, `category`, `duration`, `views_count`, `thumbnail`, `description`, `created_at`) VALUES (7, 'മൂന്നോ നാലോ വയസുള്ള കുട്ടിയാണ് കാർ ഓടിച്ചത്, കണ്ടില്ലെന്ന് നടിക്കാനാവാത്തതിനാലാണ് വീഡിയോ എടുത്തത്', 'https://youtu.be/5ZN8HygdLHo', '5ZN8HygdLHo', 'KERALA', '01:30', 1200, 'https://img.youtube.com/vi/5ZN8HygdLHo/hqdefault.jpg', '', '2026-10-31 12:47:35');

DROP TABLE IF EXISTS `subscribers`;
CREATE TABLE `subscribers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ad_inquiries`;
CREATE TABLE `ad_inquiries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `ad_type` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'Digital Banner',
  `budget` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `message` text COLLATE utf8mb4_unicode_ci,
  `status` enum('New','Contacted','Confirmed','Closed') COLLATE utf8mb4_unicode_ci DEFAULT 'New',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `photo_stories`;
CREATE TABLE `photo_stories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tag_label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'PHOTO STORY',
  `subtitle` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT 'KERALA IN FRAMES',
  `title` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `images` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data for photo_stories
INSERT INTO `photo_stories` (`id`, `tag_label`, `subtitle`, `title`, `description`, `images`, `created_at`, `updated_at`) VALUES (1, 'PHOTO STORY', 'KERALA IN FRAMES', 'കുട്ടനാടൻ കായൽ ജീവിതം: വേനൽമഴയുടെ വരവറിയിച്ച് ഓളങ്ങൾ', 'Visual captures of life, landscapes, and backwaters across God''s Own Country.', '[{"url":"https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=600&q=80","caption":"കുട്ടനാട് 1"},{"url":"https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=600&q=80","caption":"കുട്ടനാട് 2"},{"url":"https://images.unsplash.com/photo-1593693397690-362cb9666fc2?auto=format&fit=crop&w=600&q=80","caption":"കുട്ടനാട് 3"}]', '2026-11-03 04:45:50', '2026-11-03 04:45:50');

SET FOREIGN_KEY_CHECKS = 1;
